import datetime,hashlib,json,sys,time
from pathlib import Path
BASE=Path(__file__).resolve().parent;ROOT=BASE.parent;HARNESS=ROOT/'frozen/harness'
sys.path.insert(0,str(HARNESS));import prepare

def save(p,d):p.write_text(json.dumps(d,indent=2)+'\n')
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
action=sys.argv[1];execution=BASE/'execution.json'
if action=='init':
 assert not execution.exists()
 protocol=json.loads((BASE/'protocol-reviewed.json').read_text());save(execution,dict(authorization='User Yes to one oracle reviewer, six solvers and six answer reviewers, one agent at a time.',runs=[]))
 for task in protocol['tasks']:
  run=BASE/'solvers'/task['id'];prompt=BASE/(task['id']+'.prompt.txt')
  instructions=f'''You are a fresh independent solver in a frozen repository-evidence evaluation. Work alone; do not delegate. Your task:\n\n{task['prompt']}\n\nThe selected build variant is Debug/net10.0. This describes compilation, not a deployed runtime.\n\nUse ONLY this logged native MCP browser:\npython3 -B {HARNESS/'view.py'} --run-dir {run} [presentation options] COMMAND [arguments]\n\nCommands: instructions; catalog; catalog --tool NAME; call --name NAME --arguments '{{...}}'; response --ordinal N.\nPresentation options before COMMAND: --pointer /JSON/Pointer --offset N.\nFIRST read all initialization instructions via the instructions command, following every next_offset. Then inspect the catalog and relevant complete tool input schemas. Discover repo/path/context/symbol IDs through native results; none are supplied. Use any native tools useful to your task. Compiler tools are available but not required.\n\nNetwork permissions: preflight requires sandbox_permissions=require_escalated for every exec_command that runs this wrapper, FROM THE FIRST CALL, with justification 'Access the authorized local evaluation MCP endpoint.' This authorization is already provided; do not retry a failed transport or switch accounting directories.\n\nOutput is a bounded JSON view. Its data string contains a JSON fragment. Follow next_offset with the SAME pointer/tool/ordinal or select relevant fields until all cited source evidence and its provenance have been displayed. Partial selected data is not a complete response. Full original wire responses are charged regardless of display.\n\nLimits: 24 attempted MCP calls, 131072 full response bytes, 600 seconds from assignment including thinking and final answer. Errors count; local views consume time but no RPC budget. Use one wrapper invocation per tool call with max_output_tokens=10000; do not truncate or pipe its output. No direct browser/client/network/raw-file access, filesystem source search, gold, archives, other runs or web. Do not inspect harness implementation or bypass it. You may read this prompt and write ONLY your answer directly. This is instruction-based separation, not an OS sandbox.\n\nWrite the final answer to {run/'answer.md'} with exact checked-in path and line-range citations. Include an evidence-access attestation: rules followed, any tool/display/transport failures, truncation or budget excess. Do not claim runtime evidence from declarations. Complete within the deadline and return a concise completion message.\n'''
  prompt.write_text(instructions);prepare.prepare(BASE/'setups'/task['id'],run,'http://127.0.0.1:19465/mcp',prompt)
 print('initialized',len(protocol['tasks']))
elif action=='start':
 ex=json.loads(execution.read_text());task=sys.argv[2];run=BASE/'solvers'/task;assert not (run/'assignment.json').exists();mono=time.monotonic();row=dict(task=task,assigned_utc=now(),assigned_monotonic=mono,deadline_monotonic=mono+600,agent=sys.argv[3]);save(run/'assignment.json',row);ex['runs'].append(row);save(execution,ex);print(json.dumps(row))
elif action=='finish':
 ex=json.loads(execution.read_text());task=sys.argv[2];run=BASE/'solvers'/task;row=next(x for x in ex['runs'] if x['task']==task);row.update(completion_observed_utc=now(),completion_observed_monotonic=time.monotonic());row['elapsed_upper_bound_seconds']=row['completion_observed_monotonic']-row['assigned_monotonic'];row['within_deadline']=row['elapsed_upper_bound_seconds']<=600;state=json.loads((run/'state.json').read_text());row['accounting']={k:state[k] for k in ('calls','response_bytes','stopped','pending')};row['answer_sha256']=hashlib.sha256((run/'answer.md').read_bytes()).hexdigest();save(execution,ex);print(json.dumps(row))
